descriptor.templateCss:
.sem-consumption {
  height: 100%;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 14px;
  font-family: Roboto, Arial, sans-serif;
  color: rgba(0, 0, 0, 0.87);
}

.toolbar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.toolbar-left {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
  flex-wrap: wrap;
}

.toolbar-title {
  font-size: 15px;
  font-weight: 700;
  color: #0d223d;
  white-space: nowrap;
}

.periods {
  display: inline-flex;
  gap: 8px;
  flex-wrap: wrap;
}

.period,
.refresh {
  min-height: 34px;
  border: 1px solid rgba(0, 0, 0, 0.18);
  border-radius: 999px;
  background: #fff;
  color: rgba(0, 0, 0, 0.78);
  font-size: 13px;
  font-weight: 500;
  padding: 0 14px;
  cursor: pointer;
}

.period.active {
  border-color: #1565c0;
  background: #1565c0;
  color: #fff;
}

.refresh {
  border-radius: 6px;
}

.period:disabled,
.refresh:disabled {
  cursor: default;
  opacity: 0.55;
}

.options {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
  font-size: 12px;
  color: rgba(0, 0, 0, 0.67);
}

.options label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.summary {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.card {
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 8px;
  background: linear-gradient(180deg, #ffffff 0%, #f7f9fc 100%);
  padding: 10px 12px;
}

.card .label {
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: rgba(0, 0, 0, 0.54);
}

.card .value {
  margin-top: 4px;
  font-size: 16px;
  font-weight: 600;
  color: #0d223d;
}

.chart {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  border: 1px solid rgba(0, 0, 0, 0.08);
  border-radius: 8px;
  padding: 12px;
  background: #fafbfc;
}

.chart-header {
  margin-bottom: 10px;
  font-size: 12px;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.58);
}

.row {
  display: grid;
  grid-template-columns: 116px minmax(0, 1fr) 92px;
  gap: 10px;
  align-items: center;
  padding: 6px 0;
}

.meta {
  min-width: 0;
}

.meta .label {
  font-size: 13px;
  font-weight: 500;
  color: rgba(0, 0, 0, 0.82);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.meta .hint {
  margin-top: 2px;
  font-size: 11px;
  color: rgba(0, 0, 0, 0.52);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bar-shell {
  height: 12px;
  border-radius: 999px;
  background: #e6ebf2;
  overflow: hidden;
}

.bar {
  height: 100%;
  min-width: 0;
  border-radius: 999px;
  background: linear-gradient(90deg, #1565c0 0%, #42a5f5 100%);
}

.bar.missing {
  background: #b0bec5;
}

.row .value {
  text-align: right;
  font-size: 12px;
  font-weight: 600;
  color: #0d223d;
}

.row .value.missing {
  color: rgba(0, 0, 0, 0.46);
}

.empty {
  border: 1px dashed rgba(0, 0, 0, 0.16);
  border-radius: 8px;
  padding: 14px;
  background: #fafafa;
  font-size: 13px;
  color: rgba(0, 0, 0, 0.6);
}

.status {
  min-height: 54px;
  overflow: auto;
  border-left: 4px solid #9e9e9e;
  border-radius: 4px;
  padding: 8px 10px;
  background: #f7f7f7;
  font-size: 13px;
  line-height: 1.35;
}

.status.ok {
  border-left-color: #2e7d32;
  background: #eef7ef;
}

.status.error {
  border-left-color: #c62828;
  background: #fff1f1;
}

.status.busy {
  border-left-color: #ef6c00;
  background: #fff6e8;
}

.status pre {
  margin: 8px 0 0;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
}

@media (max-width: 700px) {
  .summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .row {
    grid-template-columns: 1fr;
    gap: 6px;
  }

  .row .value {
    text-align: left;
  }

  .toolbar {
    flex-direction: column;
    align-items: stretch;
  }

  .toolbar-left {
    flex-direction: column;
    align-items: flex-start;
  }

  .refresh {
    width: 100%;
  }
}

@media (max-width: 420px) {
  .summary {
    grid-template-columns: 1fr;
  }
}

descriptor.controllerScript:
self.onInit = function() {
  var $scope = self.ctx.$scope;
  var settings = self.ctx.settings || {};
  var requestTimeout = settings.requestTimeout || 30000;
  var periods = {
    '23h': {
      method: 'getConsumption23h',
      title: 'Ultimes 23 hores'
    },
    '30d': {
      method: 'getConsumption30d',
      title: 'Ultims 30 dies'
    },
    '12m': {
      method: 'getConsumption12m',
      title: 'Ultims 12 mesos'
    }
  };

  $scope.period = periods[settings.defaultPeriod] ? settings.defaultPeriod : '23h';
  $scope.busy = false;
  $scope.statusKind = 'idle';
  $scope.statusText = 'Selecciona un periode i prem Actualitzar.';
  $scope.lastResponse = '';
  $scope.payload = null;
  $scope.rawRpcResponse = null;
  $scope.rows = [];
  $scope.summary = null;
  $scope.hideEmptyRows = settings.hideEmptyRows !== false;
  $scope.showRawResponse = settings.showRawResponse === true;

  function pad(value) {
    return String(value).padStart(2, '0');
  }

  function stringify(value) {
    try {
      return JSON.stringify(value, null, 2);
    } catch (e) {
      return String(value);
    }
  }

  function setStatus(kind, text) {
    $scope.statusKind = kind;
    $scope.statusText = text;
    self.ctx.detectChanges();
  }

  function unwrapRpcResponse(response) {
    var payload = response;

    if (payload && typeof payload === 'object') {
      if (payload.success === false) {
        throw new Error(payload.error || 'RPC fallit');
      }

      if (payload.success === true && payload.data !== undefined) {
        payload = payload.data;
      }

      if (
        payload &&
        payload.data &&
        typeof payload.data === 'object' &&
        payload.data.success === true &&
        payload.data.data !== undefined
      ) {
        payload = payload.data.data;
      }
    }

    return payload;
  }

  function formatWh(value) {
    if (value === null || value === undefined || isNaN(Number(value))) {
      return 'Sense dada';
    }
    var numeric = Number(value);
    if (Math.abs(numeric - Math.round(numeric)) < 0.05) {
      return Math.round(numeric) + ' Wh';
    }
    return numeric.toFixed(1) + ' Wh';
  }

  function buildRowLabel(periodKey, sample) {
    if (periodKey === '23h') {
      return sample.isotime || sample.timestamp_local || ('-' + sample.hours_ago + ' h');
    }
    if (periodKey === '30d') {
      return sample.date || ('-' + sample.days_ago + ' d');
    }
    return sample.year_month || ((sample.year || '----') + '-' + pad(sample.month || 0));
  }

  function buildRowHint(periodKey, sample) {
    if (periodKey === '23h') {
      if (sample.timestamp_local) {
        return sample.timestamp_local;
      }
      if (sample.hours_ago === 0) {
        return 'Hora actual';
      }
      return 'Fa ' + sample.hours_ago + ' h';
    }
    if (periodKey === '30d') {
      if (sample.days_ago === 0) {
        return 'Avui';
      }
      return 'Fa ' + sample.days_ago + ' dies';
    }
    if (sample.months_ago === 0) {
      return 'Mes actual';
    }
    return 'Fa ' + sample.months_ago + ' mesos';
  }

  function buildSummary(periodKey, payload) {
    var samples = Array.isArray(payload.samples) ? payload.samples : [];
    var availableCount = 0;
    var totalWh = 0;
    var peakWh = null;
    var latestWh = null;

    for (var i = 0; i < samples.length; i += 1) {
      var value = samples[i] ? samples[i].consumption_wh : null;
      if (value === null || value === undefined || isNaN(Number(value))) {
        continue;
      }
      var numeric = Number(value);
      if (latestWh === null) {
        latestWh = numeric;
      }
      availableCount += 1;
      totalWh += numeric;
      if (peakWh === null || numeric > peakWh) {
        peakWh = numeric;
      }
    }

    return {
      title: periods[periodKey].title,
      sampleCount: payload.sample_count || samples.length,
      availableCount: availableCount,
      latestText: formatWh(latestWh),
      totalText: formatWh(totalWh),
      peakText: formatWh(peakWh)
    };
  }

  function buildRows(periodKey, payload) {
    var rows = [];
    var samples = Array.isArray(payload.samples) ? payload.samples : [];
    var maxWh = 0;

    for (var i = 0; i < samples.length; i += 1) {
      var sample = samples[i] || {};
      var rawValue = sample.consumption_wh;
      var hasValue = !(rawValue === null || rawValue === undefined || isNaN(Number(rawValue)));
      var numeric = hasValue ? Number(rawValue) : null;

      if ($scope.hideEmptyRows && !hasValue) {
        continue;
      }

      if (hasValue && numeric > maxWh) {
        maxWh = numeric;
      }

      rows.push({
        label: buildRowLabel(periodKey, sample),
        hint: buildRowHint(periodKey, sample),
        isMissing: !hasValue,
        numericValue: numeric,
        valueText: formatWh(numeric),
        widthPercent: 0
      });
    }

    for (var j = 0; j < rows.length; j += 1) {
      var row = rows[j];
      if (row.isMissing || maxWh <= 0 || row.numericValue === null) {
        row.widthPercent = row.isMissing ? 0 : 4;
        continue;
      }
      row.widthPercent = Math.max(4, Math.round((row.numericValue / maxWh) * 1000) / 10);
    }

    return rows;
  }

  function refreshRenderedView() {
    if (!$scope.payload) {
      $scope.rows = [];
      $scope.summary = null;
      $scope.lastResponse = '';
      self.ctx.detectChanges();
      return;
    }

    $scope.rows = buildRows($scope.period, $scope.payload);
    $scope.summary = buildSummary($scope.period, $scope.payload);
    $scope.lastResponse = stringify($scope.showRawResponse ? $scope.rawRpcResponse : $scope.payload);
    self.ctx.detectChanges();
  }

  function handleRpcSuccess(periodKey, payload, rawResponse) {
    if (!payload || !Array.isArray(payload.samples)) {
      $scope.busy = false;
      setStatus('error', 'La resposta RPC no te el format esperat.');
      return;
    }

    $scope.payload = payload;
    $scope.rawRpcResponse = rawResponse;
    $scope.busy = false;
    refreshRenderedView();
    setStatus('ok', periods[periodKey].title + ' actualitzat.');
  }

  function handleRpcError(rejection) {
    $scope.busy = false;
    var detail = 'RPC fallit';
    if (rejection) {
      detail = rejection.statusText || rejection.message || rejection.error || detail;
    }
    setStatus('error', detail);
  }

  function loadPeriod(periodKey) {
    var config = periods[periodKey];
    if (!config) {
      setStatus('error', 'Periode desconegut: ' + periodKey + '.');
      return;
    }

    $scope.busy = true;
    setStatus('busy', 'Carregant ' + config.title.toLowerCase() + '...');

    self.ctx.controlApi.sendTwoWayCommand(config.method, {}, requestTimeout).subscribe(
      function(response) {
        var payload;
        try {
          payload = unwrapRpcResponse(response);
        } catch (error) {
          handleRpcError(error);
          return;
        }
        handleRpcSuccess(periodKey, payload, response);
      },
      function(rejection) {
        handleRpcError(rejection);
      }
    );
  }

  $scope.selectPeriod = function(periodKey) {
    if ($scope.period === periodKey && $scope.payload) {
      loadPeriod(periodKey);
      return;
    }
    $scope.period = periodKey;
    $scope.payload = null;
    $scope.rawRpcResponse = null;
    $scope.rows = [];
    $scope.summary = null;
    $scope.lastResponse = '';
    self.ctx.detectChanges();
    loadPeriod(periodKey);
  };

  $scope.refreshCurrent = function() {
    loadPeriod($scope.period);
  };

  $scope.applyViewOptions = function() {
    refreshRenderedView();
  };

  if (settings.autoLoadOnInit !== false) {
    loadPeriod($scope.period);
  }
};

self.typeParameters = function() {
  return {
    maxDatasources: 0,
    singleEntity: true,
    previewWidth: '640px',
    previewHeight: '520px',
    embedTitlePanel: true
  };
};

self.onDestroy = function() {
};

descriptor.settingsSchema:
{
  "schema": {
    "type": "object",
    "properties": {
      "requestTimeout": {
        "title": "RPC request timeout",
        "type": "number",
        "default": 30000
      },
      "defaultPeriod": {
        "title": "Periode inicial",
        "type": "string",
        "default": "23h"
      },
      "autoLoadOnInit": {
        "title": "Carrega automaticament en obrir",
        "type": "boolean",
        "default": true
      },
      "hideEmptyRows": {
        "title": "Amaga files sense dada per defecte",
        "type": "boolean",
        "default": true
      },
      "showRawResponse": {
        "title": "Mostra JSON brut per defecte",
        "type": "boolean",
        "default": false
      }
    },
    "required": []
  },
  "form": [
    "requestTimeout",
    {
      "key": "defaultPeriod",
      "type": "select",
      "titleMap": [
        { "value": "23h", "name": "23 hores" },
        { "value": "30d", "name": "30 dies" },
        { "value": "12m", "name": "12 mesos" }
      ]
    },
    "autoLoadOnInit",
    "hideEmptyRows",
    "showRawResponse"
  ]
}
